"""Delivery examples and task guidance with native tool selection preserved."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


GUIDANCE = """预约页开发与交付

1. 开始本次预约页任务时，先读取当前工作目录中本次工作规则和完整课表；路径已给出就直接读，未知才列目录，内容截断则续读。本轮已读全且未变化的材料不要反复读取。按当期原文确定课程字段、筛选条件、名额口径、冲突边界、持久化范围及键盘要求，不套用其他门店或旧任务的规则。缺失或矛盾只记录具体缺口，不自行补业务事实、数值或政策。

2. 实现供会员在前台平板直接使用的离线单文件页面，所需样式、脚本和数据随页面自包含，不依赖联网加载。以当前材料逐项对应展示、筛选、名额与冲突判断、持久化、键盘操作的实现和验证；以会员能读懂状态、能直接操作为目的，不因平板场景额外引入身份系统或后台功能。交付前对照原文和实际代码，使用现有可用能力核验材料要求的正常、拒绝及边界情形，并检查适用的刷新恢复和键盘路径；验证失败先修复，不通过也不隐瞒。没有执行的验证不得说已通过。

3. 收尾时先对照上下文中的 booking-delivery-contract 案例，把“成品交付”和“最终回复”分开。本次只交成品时，磁盘上的指定 HTML 必须用 deliver_files 实际交付，不交测试脚本；成功回执后，只用当期规则允许的空回复、仅文件名或仅真实交付链接，允许文件名时直接回复本次指定文件名，不加“已交付”等完成宣告，不编造链接。不能交文件且规则允许兜底时，才只给一个标注 html 的完整代码块，无省略、前后无说明；显式要求代码形式时照当期要求。两条分支二选一，文件名不代替实际交付。不要先写总结：不附加实现介绍、操作步骤、自测结果或其他代码块，也不把报告搬进 HTML、额外文件或 deliver_files 的 message/description。普通质量检查受阻或材料局部缺失时，仍在本轮交付有依据的已完成部分，仅在成品中简明标明真正影响使用的缺口，不放开发日志，不用进度说明代替成品，不将不确定内容写成已实现或已验证。
"""


class BookingPageCapability(CapabilityStrategy):
    """Supply guidance without storing business facts or changing permissions."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    # Inherited prepare registers this resource and propagates refusals.
    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        return (
            SkillContribution(
                name="booking-delivery-contract",
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets["skills/booking-delivery-contract/SKILL.md"]},
                source="booking-delivery-examples",
            ),
        )

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        matches = [skill for skill in request.skills if skill.name == "booking-delivery-contract"]
        if len(matches) != 1 or not matches[0].available:
            return CapabilitySelection(
                tools=None,
                skills=None,
                guidance=GUIDANCE + "\n本次未能供给交付案例正文；按上述规则和当期材料继续完成，"
                "不声称已参考案例，不另行搜索或重读来补这个内部资源。"
                "此内部资源状态不写进用户回复。",
            )

        # Count all views: even an unavailable duplicate makes a key ambiguous.
        counts: dict[tuple[str, str], int] = {}
        for skill in request.skills:
            key = (skill.source, skill.name)
            counts[key] = counts.get(key, 0) + 1
        selections = tuple(
            SkillSelection(
                name=skill.name,
                source=skill.source,
                delivery="body" if skill.name == "booking-delivery-contract" else "catalog",
            )
            for skill in request.skills
            if skill.available and counts[(skill.source, skill.name)] == 1
        )
        return CapabilitySelection(tools=None, skills=selections, guidance=GUIDANCE)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> BookingPageCapability:
    """Bind the host registrar without mutating the checkpoint or task."""
    return BookingPageCapability(registrar)
